52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    /**
60	     * Monotonically increasing sequence assigned to each {@code OWNER_CREATED} structured event, in
61	     * the order owners are created across this application instance. Shared across all requests.
62	     */
63	    private static final java.util.concurrent.atomic.AtomicLong OWNER_EVENT_SEQ =
64	        new java.util.concurrent.atomic.AtomicLong();
65	
66	    /** Serializes the immutable {@link OwnerCreatedEvent} to its canonical JSON form. */
67	    private static final tools.jackson.databind.ObjectMapper AUDIT_EVENT_MAPPER =
68	        tools.jackson.databind.json.JsonMapper.builder().build();
69	
70	    /**
71	     * Immutable structured audit event emitted alongside the human-readable audit line when an owner
72	     * is created. Its component order is also its JSON field order: {@code seq}, {@code ownerId},
73	     * {@code customerCode}, {@code membershipLevel}, {@code event}. The {@code customerCode} component
74	     * carries the owner's <em>current primary identifier</em>; today that is the customer code, and it
75	     * is the single field a later checkpoint repoints when the identity is unified into the memberId.
76	     */
77	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
78	        Integer membershipLevel, String event) {
79	    }
80	
81	    /**
82	     * Remembers, per seen {@code Idempotency-Key} header, the id of the owner originally created for
83	     * that key, so a repeated create carrying the same key returns that owner instead of creating a
84	     * duplicate. Kept in memory and keyed on the opaque client-supplied value.
85	     */
86	    private static final java.util.Map<String, Integer> IDEMPOTENCY_KEYS =
87	        new java.util.concurrent.ConcurrentHashMap<>();
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
