122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already seen, return
136	        // the owner originally created for that key with 200 OK, rather than creating a duplicate (which
137	        // the identity/household duplicate rules would otherwise reject with 409).
138	        String idempotencyKey = currentIdempotencyKey();
139	        if (idempotencyKey != null) {
140	            Integer existingId = IDEMPOTENCY_KEYS.get(idempotencyKey);
141	            if (existingId != null) {
142	                Owner existing = this.clinicService.findOwnerById(existingId);
143	                if (existing != null) {
144	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
145	                }
146	            }
147	        }
148	        HttpHeaders headers = new HttpHeaders();
149	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
150	        applyAddress(owner);
151	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
152	        owner.setTelephone(normalizedTelephone);
153	        owner.setEmail(normalizeEmail(owner.getEmail()));
154	        validateEmailDomain(owner.getEmail());
155	        validatePostcode(owner.getPostcode(), owner.getCity());
156	        java.time.LocalDate serverDate = java.time.LocalDate.now();
157	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
158	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
159	                "Registration date must not be later than the current server date");
160	        }
161	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
162	            ? owner.getRegistrationDate() : serverDate;
163	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
164	        owner.setRegistrationDate(businessDate);
165	        long createdToday = this.clinicService.findAllOwners().stream()
166	            .map(Owner::getRegistrationDate)
167	            .filter(businessDate::equals)
168	            .count();
169	        if (createdToday >= 100) {
170	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
171	                "The maximum number of owners for today has already been reached");
172	        }
173	        owner.setBulkSignupWarning(createdToday > 80);
174	        // The household is keyed deterministically on (normalized last name, postcode): every owner
175	        // computes the same householdId from those two fields, so owners sharing a last name and
176	        // postcode belong to the same household automatically, without any explicit linking.
177	        String lastNameKey = normalizeForHousehold(owner.getLastName());
178	        String householdId = householdId(lastNameKey, owner.getPostcode());
179	        owner.setHouseholdId(householdId);
180	        // Soft-deleted owners are excluded from all duplicate/identity detection: a deleted owner
181	        // no longer blocks a new owner that would otherwise match it.
182	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
183	            .filter(existing -> !existing.isDeleted())
184	            .filter(existing -> householdId.equals(
185	                householdId(normalizeForHousehold(existing.getLastName()), existing.getPostcode())))
186	            .toList();
187	        // All duplicate detection is expressed through the single derived identityKey, the SHA-256
188	        // hex of (normalizedTelephone|lowerEmail|soundex(lastName)); a new owner is rejected only
189	        // when its whole key matches an existing (non-deleted) owner's.
190	        String identityKey = owner.getIdentityKey();
191	        boolean identityInUse = this.clinicService.findAllOwners().stream()
192	            .filter(existing -> !existing.isDeleted())
193	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
194	        if (identityInUse) {
195	            throw new ResponseStatusException(HttpStatus.CONFLICT,
196	                "An owner with this identity already exists");
197	        }
198	        // Duplicate detection is now the single identity key above; because the telephone is part of
199	        // that key, two owners sharing a last name and postcode but with different telephones have
200	        // different keys and are both admitted, so the former household-duplicate 409 no longer
201	        // applies. Declaring 'sharesHousehold' marks the new owner as a declared household member.
202	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
203	        // An undeclared new owner joining an existing household while carrying its own (distinct)
204	        // email address joins as a member whose membership level is capped below.
205	        boolean distinguishableByEmail = owner.getEmail() != null && !owner.getEmail().isBlank()
206	            && householdMembers.stream()
207	                .noneMatch(existing -> owner.getEmail().equalsIgnoreCase(existing.getEmail()));
208	        boolean joinsExistingHousehold = !householdMembers.isEmpty()
209	            && !declaredHouseholdMember && distinguishableByEmail;
210	        String cityKey = normalizeForHousehold(owner.getCity());
211	        long cityCount = this.clinicService.findAllOwners().stream()
212	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
213	            .count();
214	        if (cityCount >= 50) {
215	            throw new ResponseStatusException(HttpStatus.CONFLICT,
216	                "This city already has the maximum number of owners");
217	        }
218	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
219	        owner.setHouseholdSize(householdMembers.size() + 1);
220	        // A new owner joining an existing household cannot rank more than one level above the current
221	        // maximum membership level among their household members: its level is capped there. With no
222	        // existing household member (the usual case) no cap applies and the level stays as derived.
223	        if (joinsExistingHousehold) {
224	            int naturalLevel = Owner.membershipLevel(Owner.membershipPoints(owner));
225	            int maxMemberLevel = householdMembers.stream()
226	                .mapToInt(Owner::effectiveMembershipLevel)
227	                .max().orElse(0);
228	            owner.setMembershipLevel(Math.min(naturalLevel, maxMemberLevel + 1));
229	        }
230	        // Soft match: a new owner whose identityKey differs from every existing owner but whose
231	        // soundex(lastName) and postcode both match an existing (non-deleted) owner is flagged as a
232	        // possible duplicate of the earliest such owner. Soft-deleted owners are ignored, matching
233	        // the identity check above.
234	        String lastNameSoundex = Owner.soundex(owner.getLastName());
235	        Owner softMatch = this.clinicService.findAllOwners().stream()
236	            .filter(existing -> !existing.isDeleted())
237	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
238	            .filter(existing -> owner.getPostcode() != null
239	                && owner.getPostcode().equals(existing.getPostcode()))
240	            .filter(existing -> lastNameSoundex.equals(Owner.soundex(existing.getLastName())))
241	            .min(java.util.Comparator.comparing(Owner::getId))
242	            .orElse(null);
243	        if (softMatch != null) {
244	            owner.setPossibleDuplicate(true);
245	            owner.setPossibleDuplicateOf(softMatch.getId());
246	        } else {
247	            owner.setPossibleDuplicate(false);
248	            owner.setPossibleDuplicateOf(null);
249	        }
250	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(owner.getCity(), owner.getPostcode(),
251	            owner.getTelephone(), owner.getLastName())));
252	        this.clinicService.saveOwner(owner);
253	        if (idempotencyKey != null) {
254	            IDEMPOTENCY_KEYS.put(idempotencyKey, owner.getId());
255	        }
256	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
257	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
258	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
259	            ownerDto.getMembershipNumber());
260	        // The event's primary identifier is the owner's customerCode today; a later checkpoint unifies
261	        // it into the memberId and repoints this single expression, and the event carries that instead.
262	        String primaryIdentifier = owner.getCustomerCode();
263	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_EVENT_SEQ.incrementAndGet(),
264	            owner.getId(), primaryIdentifier, ownerDto.getMembershipLevel(), "OWNER_CREATED");
265	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
266	        headers.setLocation(UriComponentsBuilder.newInstance()
267	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
268	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
269	    }
270	
271	    /**
272	     * Reads the current request's {@code Idempotency-Key} header, if any. Returns the trimmed header
273	     * value, or {@code null} when the header is absent, blank, or there is no active request (so a
274	     * request without the header behaves exactly as before).
275	     *
276	     * @return the non-blank idempotency key for the current request, or {@code null}
277	     */
278	    private String currentIdempotencyKey() {
279	        org.springframework.web.context.request.RequestAttributes attrs =
280	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
281	        if (!(attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs)) {
282	            return null;
283	        }
284	        String key = servletAttrs.getRequest().getHeader("Idempotency-Key");
285	        if (key == null || key.isBlank()) {
286	            return null;
287	        }
288	        return key.trim();
289	    }
290	
291	    /**
292	     * The fixed public-holiday calendar the business-day roll skips. When an adjusted registration
293	     * date lands on one of these dates it is rolled forward to the next non-holiday business day.
294	     */
295	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
296	        java.time.LocalDate.parse("2026-01-01"), java.time.LocalDate.parse("2026-01-26"),
297	        java.time.LocalDate.parse("2026-04-25"), java.time.LocalDate.parse("2026-12-25"),
298	        java.time.LocalDate.parse("2026-12-28"));
299	
300	    /**
301	     * Rolls a registration date forward to a business day. A Saturday, Sunday or listed public
302	     * holiday is advanced one day at a time until it lands on a weekday that is not a public holiday;
303	     * a plain weekday is returned unchanged. This is applied to the effective registration date
304	     * (whether supplied in the request or defaulted to the server date) so that every stored
305	     * {@code registrationDate}, and any value derived from it, lands on a business day.
306	     *
307	     * @param date the effective registration date
308	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
309	     */
310	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
311	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
312	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
313	            || PUBLIC_HOLIDAYS.contains(date)) {
314	            date = date.plusDays(1);
315	        }
316	        return date;
317	    }
318	
319	    /**
320	     * Counts the owners that already exist (before the current create) whose first and last names
321	     * both match the supplied names, compared case-insensitively. The returned value is captured on
322	     * the new owner at creation time and does not change as further owners are added later.
323	     *
324	     * @param firstName the new owner's first name
325	     * @param lastName  the new owner's last name
326	     * @return the number of pre-existing namesake owners
327	     */
328	    private int namesakeCount(String firstName, String lastName) {
329	        return (int) this.clinicService.findAllOwners().stream()
330	            .filter(existing -> existing.getFirstName() != null
331	                && existing.getFirstName().equalsIgnoreCase(firstName)
332	                && existing.getLastName() != null
333	                && existing.getLastName().equalsIgnoreCase(lastName))
334	            .count();
335	    }
336	
337	    /**
338	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where
339	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
340	     * the city when the postcode is absent or in no known range, see
341	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}), and
342	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
343	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike
344	     * the previous city-prefixed scheme it carries no per-city sequence number, so the identity is
345	     * a pure function of the owner's region, telephone and last name.
346	     *
347	     * @param city                the owner's city
348	     * @param postcode            the owner's postcode, may be {@code null}
349	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
350	     * @param lastName            the owner's last name
351	     * @return the assigned customer code
352	     */
353	    private String customerCode(String city, String postcode, String normalizedTelephone, String lastName) {
354	        String region = org.springframework.samples.petclinic.mapper.Localities
355	            .forCityAndPostcode(city, postcode);
356	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
357	            + (lastName == null ? "" : lastName), 8);
358	        return region + "-" + hash8;
359	    }
360	
361	    /**
362	     * Ensures the computed {@code customerCode} is unique across existing owners. When {@code baseCode}
363	     * does not collide with any existing owner's {@code customerCode} it is returned unchanged.
364	     * Otherwise {@code '-<n>'} is appended, using the smallest {@code n} of 2 or more that yields a
365	     * value not already in use, and that de-duplicated code is returned.
366	     *
367	     * @param baseCode the freshly computed customer code
368	     * @return {@code baseCode} if unused, otherwise {@code baseCode + "-" + n} for the smallest free n
369	     */
370	    private String deduplicateCustomerCode(String baseCode) {
371	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
372	            .map(org.springframework.samples.petclinic.model.Owner::getCustomerCode)
373	            .filter(java.util.Objects::nonNull)
374	            .collect(java.util.stream.Collectors.toSet());
375	        if (!inUse.contains(baseCode)) {
376	            return baseCode;
377	        }
378	        int n = 2;
379	        while (inUse.contains(baseCode + "-" + n)) {
380	            n++;
381	        }
382	        return baseCode + "-" + n;
383	    }
384	
385	    /**
386	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
387	     * UTF-8 bytes of {@code value}.
388	     *
389	     * @param value  the source value to hash
390	     * @param length the number of leading hex characters to return
391	     * @return the leading upper-case hex characters of the digest
392	     */
393	    private String sha256UpperHex(String value, int length) {
394	        try {
395	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
396	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
397	            StringBuilder sb = new StringBuilder(digest.length * 2);
398	            for (byte b : digest) {
399	                sb.append(String.format("%02x", b));
400	            }
401	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
402	        }
403	        catch (java.security.NoSuchAlgorithmException e) {
404	            throw new IllegalStateException("SHA-256 not available", e);
405	        }
406	    }
