408	    /**
409	     * Normalizes a street address applied whenever an owner is created: leading and trailing
410	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
411	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
412	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
413	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
414	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
415	     * {@code '12 MAIN STREET'}.
416	     *
417	     * @param address the raw address as submitted, or {@code null} when absent
418	     * @return the normalized address, or the empty string when the value is blank
419	     */
420	    /**
421	     * Resolves and normalizes an owner's postal address, accepting either the structured form
422	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
423	     * input for backward compatibility. The structured form is preferred: when a non-blank
424	     * {@code addressLine1} is supplied, both structured lines are normalized (see
425	     * {@link #normalizeAddress(String)}) and the stored {@code address} is composed from them —
426	     * the normalized {@code addressLine1}, with a single space and the normalized
427	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the flat
428	     * {@code address} input is normalized and stored, and the structured lines are cleared.
429	     *
430	     * <p>An owner is valid only when it supplies an address in one of these forms; a request with
431	     * neither a non-blank {@code addressLine1} nor a non-blank flat {@code address} is rejected.
432	     *
433	     * @param owner the owner whose address fields are resolved and normalized in place
434	     * @throws ResponseStatusException with a 400 status when no address is supplied in either form
435	     */
436	    private void applyAddress(Owner owner) {
437	        String line1 = normalizeAddress(owner.getAddressLine1());
438	        String line2 = normalizeAddress(owner.getAddressLine2());
439	        String flat = normalizeAddress(owner.getAddress());
440	        String composed;
441	        if (!line1.isEmpty()) {
442	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
443	            owner.setAddressLine1(line1);
444	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
445	        } else {
446	            composed = flat;
447	            owner.setAddressLine1(null);
448	            owner.setAddressLine2(null);
449	        }
450	        if (composed.isEmpty()) {
451	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
452	                "Address must not be blank after normalization");
453	        }
454	        owner.setAddress(composed);
455	    }
456	
457	    private String normalizeAddress(String address) {
458	        String collapsed = (address == null ? "" : address)
459	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
460	        if (collapsed.isEmpty()) {
461	            return "";
462	        }
463	        String[] tokens = collapsed.split(" ");
464	        for (int i = 0; i < tokens.length; i++) {
465	            switch (tokens[i]) {
466	                case "ST" -> tokens[i] = "STREET";
467	                case "RD" -> tokens[i] = "ROAD";
468	                case "AVE" -> tokens[i] = "AVENUE";
469	                default -> { }
470	            }
471	        }
472	        return String.join(" ", tokens);
473	    }
474	
475	    /**
476	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
477	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
478	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
479	     * empty string.
480	     *
481	     * @param value the raw value (last name or address) as submitted
482	     * @return the normalized comparison key
483	     */
484	    private String normalizeForHousehold(String value) {
485	        if (value == null) {
486	            return "";
487	        }
488	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
489	    }
490	
491	    /**
492	     * Derives the stable shared household identifier for a household, keyed on the normalized last
493	     * name and address. Because it is a pure function of those normalized keys, every owner in the
494	     * same household deterministically computes the same value. The identifier is the first 12
495	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
496	     * (the separator prevents distinct name/address pairs from colliding).
497	     *
498	     * @param lastNameKey the normalized last-name comparison key
