527	    /**
528	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
529	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
530	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
531	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
532	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
533	     * is stored as {@code '+61412345678'}.
534	     *
535	     * <p>In addition, when the number's country code has a fixed national-number length (see
536	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
537	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
538	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
539	     *
540	     * @param telephone the raw telephone number as submitted
541	     * @return the normalized E.164 telephone number
542	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
543	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
544	     *         for its country code
545	     */
546	    private String normalizeTelephone(String telephone) {
547	        String raw = telephone == null ? "" : telephone.trim();
548	        String digits = raw.replaceAll("\\D", "");
549	        String e164;
550	        if (raw.startsWith("+")) {
551	            e164 = "+" + digits;
552	        } else {
553	            if (digits.startsWith("0")) {
554	                digits = digits.substring(1);
555	            }
556	            e164 = "+61" + digits;
557	        }
558	        int digitCount = e164.length() - 1;
559	        if (digitCount < 8 || digitCount > 15) {
560	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
561	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
562	        }
563	        validateNationalNumberLength(e164);
564	        return e164;
565	    }
