567	    /**
568	     * Validates that an E.164 number's national-number length is correct for its country code.
569	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
570	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
571	     * following it must match exactly. Country codes without a fixed length are left unchecked.
572	     *
573	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
574	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
575	     *         for the country code
576	     */
577	    private void validateNationalNumberLength(String e164) {
578	        String allDigits = e164.substring(1);
579	        String bestCode = null;
580	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
581	            if (allDigits.startsWith(code)
582	                    && (bestCode == null || code.length() > bestCode.length())) {
583	                bestCode = code;
584	            }
585	        }
586	        if (bestCode == null) {
587	            return;
588	        }
589	        int nationalLength = allDigits.length() - bestCode.length();
590	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
591	        if (nationalLength != required) {
592	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
593	                "Telephone for country code '+" + bestCode + "' must have " + required
594	                    + " national digits");
595	        }
596	    }
